file="report-2026.tar.gz"
name="Ada"

echo "${name:-unknown}"      # Ada (fallback when unset or empty)
echo "${missing:-fallback}"  # fallback
echo "${#name}"              # 3 (length in characters)
echo "${file%.tar.gz}"       # report-2026 (strip shortest suffix)
echo "${file#report-}"       # 2026.tar.gz (strip shortest prefix)26.tar.gz (strip shortest prefix)
echo "${name^^}"             # ADA (uppercase)
echo "${name,}"              # ada (lowercase first character)

path="/home/ada/notes/todo.txt"

echo "${path/ada/grace}"     # /home/grace/notes/todo.txt
echo "${path//\//-}"         # -home-ada-notes-todo.txt
echo "${path##*/}"           # todo.txt (basename)
echo "${path%/*}"            # /home/ada/notes (dirname)
echo "${path:6:3}"           # ada (offset 6, length 3)

# case matches glob patterns and stops at the first match
case "$1" in
  start)   echo "starting" ;;
  stop)    echo "stopping" ;;
  restart) echo "restarting" ;;
  *)       echo "usage: $0 start|stop|restart" ;;
esac

# Numeric comparisons in a test expression
if [ "$age" -ge 18 ]; then
  echo "adult"
fi

# Two equivalent definitions
greet() {
  local name="$1"
  echo "Hello, $name"
}

function add {
  echo "$(( $1 + $2 ))"
}

greet "Ada"
add 2 3

# The return value is an exit status, not a string
is_even() {
  (( $1 % 2 == 0 ))
}
is_even 4 && echo "4 is even"

# Parse options with getopts
while getopts ":v:o:" opt; do
  case "$opt" in
    v) verbose="$OPTARG" ;;
    o) output="$OPTARG" ;;
    \?) echo "unknown option: -$OPTARG" >&2; exit 1 ;;
    :)  echo "option -$OPTARG needs a value" >&2; exit 1 ;;
  esac
done
shift $((OPTIND - 1))

echo "verbose=$verbose output=$output rest=$*"

#!/usr/bin/env bash
set -euo pipefail

# -e: exit on a failed command
# -u: error on an unset variable
# -o pipefail: a failed stage fails the pipeline

main() {
  local target="${1:?usage: $0 TARGET}"
  echo "working on $target"
}

main "/tmp"
